import React, {forwardRef, useCallback, useMemo} from 'react';

import type {SelectOption} from '@gravity-ui/uikit';
import debounce from 'lodash/debounce';

import type {MultiSelectProps} from './MultiSelect';
import {MultiSelect} from './MultiSelect';
import {filterAutocompleteOption} from './utils/filterAutocompleteOption';

export type MultiAutocompleteProps = Omit<MultiSelectProps, 'filterable' | 'value' | 'onUpdate'> & {
    value?: SelectOption[];
    onUpdate: (value: SelectOption[]) => void;
    searchDelay?: number;
};

export const MultiAutocomplete = forwardRef<HTMLButtonElement, MultiAutocompleteProps>(
    ({options, value, onUpdate, onFilterChange, searchDelay, ...props}, ref) => {
        const handleFilterChange = useMemo(
            () => (onFilterChange ? debounce(onFilterChange, searchDelay) : undefined),
            [onFilterChange, searchDelay],
        );

        const optionsWithValue = useMemo(() => {
            return [
                ...(value ?? []),
                ...(options ?? []).filter(
                    (option) =>
                        !value?.some(
                            (valueItem) => 'value' in option && option.value === valueItem.value,
                        ),
                ),
            ];
        }, [options, value]);

        const handleUpdate = useCallback(
            (newValue: string[]) => {
                onUpdate(
                    newValue.map(
                        (valueItem) =>
                            optionsWithValue.find(
                                (option) => 'value' in option && option.value === valueItem,
                            ) as SelectOption,
                    ),
                );
            },
            [onUpdate, optionsWithValue],
        );

        const selectValue = useMemo(() => value?.map((valueItem) => valueItem.value), [value]);

        return (
            <MultiSelect
                {...props}
                ref={ref}
                onUpdate={handleUpdate}
                value={selectValue}
                options={optionsWithValue}
                onFilterChange={handleFilterChange}
                filterable
                filterOption={filterAutocompleteOption}
            />
        );
    },
);

MultiAutocomplete.displayName = 'MultiAutocomplete';
